AND ChnlCode = #{pChnlCode}
AND (UploadStartDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND UploadStartDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY))
